import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"序卦传","description":"周易尚氏学 - 序卦传","frontmatter":{"title":"序卦传","description":"周易尚氏学 - 序卦传"},"headers":[],"relativePath":"zh/classics/shangshi/073.md","filePath":"zh/classics/shangshi/073.md"}'),r={name:"zh/classics/shangshi/073.md"};function i(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"序卦传",tabindex:"-1"},[l("序卦传 "),e("a",{class:"header-anchor",href:"#序卦传","aria-label":"Permalink to “序卦传”"},"​")],-1),e("p",null,"序卦上经始乾坤。终坎离。而以否泰为枢纽。下经始咸恒。终既未济。而以损益为枢。其间次序。皆有深意。圣人虑后世妄人。或有乱其卦序者。故为此以绾毂之。其意义可不深求也。",-1),e("p",null,"有天地然后万物生焉。盈天地之间者唯万物。故受之以屯。屯者盈也。屯者物之始生也。物生必蒙。故受之以蒙。蒙者蒙也。物之稚也。物稚不可不养也。故受之以需。需者饮食之道也。饮食必有讼。故受之以讼。讼必有众起。故受之以师。师者众也。众必有所比。故受之以比。比者比也。比必有所畜。故受之以小畜。物畜然后有礼。故受之以履。履而泰。然后安。故受之以泰。泰者通也。物不可以终通。故受之以否。物不可以终否。故受之以同人。与人同者。物必归焉。故受之以大有。大者不可以盈。故受之以谦。有大而能谦必豫。故受之以豫。豫必有随。故受之以随。以喜随人者必有事。故受之以蛊。蛊者事也。有事而后可大。故受之以临。临者大也。物大然后可观。故受之以观。可观而后有所合。故受之以噬嗑。嗑者合也。物不可以苟合而已。故受之以贲。贲者饰也。致饰然后亨则尽矣。故受之以剥。剥者剥也。物不可以终尽。剥穷上反下。故受之以复。复则不妄矣。故受之以天妄。有元妄然后可畜。故受之以大畜。物畜然后可养。故受之以颐。颐者养也。不养则不可动。故受之以大过。物不可以终过。故受之以坎。坎者陷也。陷必有所丽。故受之以离。离者丽也。",-1),e("p",null,"离丽者。言一阴丽于二阳之间。",-1),e("p",null,"天地然后有万物。有万物然后有男女。有男女然后有夫妇。有夫妇然后有父子。有父子然后有君臣。有君臣然后有上下。有上下然后礼义有所错。夫妇之道指咸卦不可以不久也。故受之以恒。恒者久也。物不以久居其所。故受之以遁。遁者退也。物不可以终遁。故受之以大壮。物不可以终壮。故受之以晋。晋者进也。进必有所伤。故受之以明夷夷者伤也。伤于外者。必反其家。故受之以家人。家道穷必乖。故受之以睽。睽者乖也。乖必有难。故受之以蹇。蹇者难也。物不可以终难。故受之以解。解者缓也。缓必有所失。故受之以损。损而不巳必益。故受之以益。益而不已必决。故受之以夬。夬者决也。决必有所遇。故受之以垢。姤者遇也。物相遇而后聚。故受之以苯。萃者聚也。聚而上者谓之升。故受之以升。升而不已必困。故受之以困。困乎上者必反下。故受之以并。井道不可不革。故受之以革。革物者莫若鼎。故受之以鼎。主器者莫若长子。故受之以震。震者动也。物不可以终动。止之。故受之以艮。艮者止也。物不可以终止。故受之以渐。渐者进也。进必有所归。故受之以归妹。得其所归者必大。故受之以丰。丰者大也。穷大者必失其居。故受之以旅。放而天所容。故受之以巽。巽者人也。入而后说之。故受之以兑。兑者说也。说而后散之。故受之以涣。涣者离也。物不可以终离。故受之以节。节而信之。故受之以中孚。有其信者必行之。故受之以小过。有过物者必济。故受之以既济。物不可穷也。故受之以未济终焉。",-1),e("p",null,"伏羲未定婚礼以前。人皆知有母。不知有父。故曰有夫妇然后有父子。节者符也。以竹为之。各持其一。合之以为信。周礼地官掌节是也。物不可终离。故受之以节。节之用在合。故与离对文。合而符则信。故曰节而信之。全指符节言。旧解皆误。",-1)])])}const _=s(r,[["render",i]]);export{u as __pageData,_ as default};
